<script setup>
import { computed, ref } from 'vue'
import { DEFAULT_THEME_ID, INITIAL_VISUAL_THEMES, loadVisualThemes, persistVisualThemes, parseVisualThemeJson, removeVisualTheme, validateVisualTheme } from '@/services/visualThemes'
import { useVisualThemes } from '@/composables/useVisualThemes'
import VisualThemePreview from './VisualThemePreview.vue'
const props=defineProps({userRole:String,posts:{type:Array,default:()=>[]},usageComplete:Boolean,embedded:Boolean})
const {themes,enabled,refresh}=useVisualThemes()
const selected=ref(DEFAULT_THEME_ID),draft=ref(''),notice=ref(loadVisualThemes().error),error=ref('')
const isNew=ref(false)
const parsed=computed(()=>{try{return parseVisualThemeJson(draft.value)}catch{return null}})
const locked=computed(()=>props.userRole!=='admin')
const usage=computed(()=>props.posts.filter(p=>p.visualThemeId===selected.value).length)
function choose(id){selected.value=id;isNew.value=false;draft.value=JSON.stringify(themes.value.find(t=>t.id===id),null,2);error.value='';notice.value=''}
choose(selected.value)
function attempt(action){error.value='';notice.value='';try{if(locked.value)throw Error('Solo administradores.');action()}catch(e){error.value=e.message}}
function commit(items,message){persistVisualThemes(items,props.userRole);refresh();notice.value=message}
function create(duplicate=false){attempt(()=>{const source=duplicate?parseVisualThemeJson(draft.value):INITIAL_VISUAL_THEMES[0];const theme={...structuredClone(source),id:'tema-'+crypto.randomUUID(),name:duplicate?source.name+' (copia)':'Nuevo tema',version:1,archived:false};selected.value=theme.id;isNew.value=true;draft.value=JSON.stringify(theme,null,2);notice.value='Borrador local. Revisa el JSON y guarda para añadirlo.'})}
function save(){attempt(()=>{const value=parseVisualThemeJson(draft.value);if(!isNew.value&&value.id!==selected.value)throw Error('El identificador de un tema guardado es estable. Duplica para crear otro.');if(isNew.value&&themes.value.some(t=>t.id===value.id))throw Error('Ese identificador ya existe.');const prior=themes.value.find(t=>t.id===selected.value);if(prior&&!isNew.value)value.version=Math.max(prior.version+1,value.version);commit([...themes.value.filter(t=>t.id!==value.id),value],'Tema guardado solo en este navegador.');choose(value.id);notice.value='Tema guardado solo en este navegador.'})}
function archive(){attempt(()=>{if(selected.value===DEFAULT_THEME_ID)throw Error('El tema predeterminado no se puede archivar.');const theme=themes.value.find(t=>t.id===selected.value);commit(themes.value.map(t=>t.id===theme.id?{...t,archived:!t.archived,version:t.version+1}:t),'Estado actualizado. Los posts conservan su referencia y usan el diseño predeterminado si se archiva.');draft.value=JSON.stringify(themes.value.find(t=>t.id===selected.value),null,2)})}
function remove(){attempt(()=>{const next=removeVisualTheme(themes.value,selected.value,{role:props.userRole,posts:props.posts,usageComplete:props.usageComplete});commit(next,'Tema eliminado.');choose(DEFAULT_THEME_ID);notice.value='Tema eliminado de la biblioteca local.'})}
function restore(){attempt(()=>{const preset=INITIAL_VISUAL_THEMES.find(t=>t.id===selected.value);const current=themes.value.find(t=>t.id===selected.value)||parseVisualThemeJson(draft.value);draft.value=JSON.stringify({...structuredClone(preset||INITIAL_VISUAL_THEMES[0]),id:current.id,name:current.name,version:current.version},null,2);notice.value='Valores iniciales cargados en el borrador. Pulsa Guardar para confirmar.'})}
async function importFile(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>50000)throw Error('Archivo demasiado grande.');const theme=parseVisualThemeJson(await file.text());draft.value=JSON.stringify(theme,null,2);selected.value=theme.id;isNew.value=!themes.value.some(t=>t.id===theme.id);notice.value='Importación validada. Revisa la muestra y guarda para aplicarla.';error.value=''}catch(e){error.value=e.message}finally{event.target.value=''}}
function exportFile(){attempt(()=>{const value=parseVisualThemeJson(draft.value);const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=value.id+'-v'+value.version+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
function integration(key,value){attempt(()=>{localStorage.setItem('galaxia-visual-theme-integrations',JSON.stringify({...enabled.value,[key]:value}));window.dispatchEvent(new Event('galaxia-themes-changed'));refresh();notice.value='Integración actualizada solo en este navegador.'})}
function changeColor(group,key,value){try{const next=JSON.parse(draft.value);next.config[group][key]=value;draft.value=JSON.stringify(next,null,2)}catch{error.value='Corrige primero el JSON.'}}
const labels={general:'Colores generales',social:'Carrusel social',web:'Artículo web'}
defineExpose({createTheme:()=>create()})
</script>
<template>
 <section class="visual-theme-manager">
  <header v-if="!embedded"><div><h2>Temas Visuales</h2><p>Prueba local · no sincroniza con Firebase ni cambia publicaciones existentes.</p></div><button type="button" :disabled="locked" @click="create()">+ Crear tema</button></header>
  <div v-if="locked" role="alert">Solo los administradores pueden gestionar temas.</div>
  <template v-else>
   <div class="theme-integrations"><label><input type="checkbox" :checked="enabled.web" @change="integration('web',$event.target.checked)"> Aplicar en artículos web</label><label><input type="checkbox" :checked="enabled.social" @change="integration('social',$event.target.checked)"> Aplicar en generador social</label></div>
   <p v-if="error" role="alert" class="theme-error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
   <div class="theme-manager-layout">
    <nav aria-label="Temas disponibles"><button v-for="theme in themes" :key="theme.id" type="button" :class="{selected:selected===theme.id}" @click="choose(theme.id)"><span class="theme-swatches"><i v-for="color in [theme.config.general.primary,theme.config.general.secondary,theme.config.general.highlight]" :key="color" :style="{background:color}"></i></span>{{theme.name}}<small>v{{theme.version}}{{theme.archived?' · Archivado':''}}</small></button></nav>
    <div class="theme-draft"><h3>{{isNew?'Nuevo tema':'Editar tema'}} <small v-if="!isNew">· {{usage}} publicaciones en la lista cargada</small></h3><label>Configuración JSON<textarea v-model="draft" spellcheck="false" aria-label="Configuración JSON del tema"></textarea></label>
     <div class="theme-actions"><button type="button" @click="save" :disabled="!parsed">Guardar tema</button><button type="button" @click="create(true)" :disabled="!parsed">Duplicar</button><label class="theme-file">Importar JSON<input type="file" accept=".json,application/json" @change="importFile"></label><button type="button" :disabled="!parsed" @click="exportFile">Exportar JSON</button><button type="button" @click="restore">Restaurar valores</button><button v-if="!isNew&&selected!==DEFAULT_THEME_ID" type="button" @click="archive">Archivar / reactivar</button><button v-if="!isNew&&selected!==DEFAULT_THEME_ID" type="button" :disabled="!usageComplete||usage>0" @click="remove">Eliminar sin uso</button></div>
     <small v-if="!usageComplete">Eliminación desactivada: no se ha podido verificar el uso en publicaciones.</small>
     <details v-for="(label,group) in labels" :key="group"><summary>{{label}}</summary><div v-if="parsed" class="theme-colors"><label v-for="(value,key) in parsed.config[group]" :key="key">{{key}}<input v-if="typeof value==='string'&&value.startsWith('#')" :value="value" @change="changeColor(group,key,$event.target.value)"><span v-else>{{value}}</span></label></div><p v-else>Corrige el JSON para mostrar los controles.</p></details>
    </div>
    <aside><VisualThemePreview v-if="parsed" :theme="parsed"/><p v-else>La muestra aparecerá cuando el JSON sea válido y tenga contraste suficiente.</p><small>La muestra ilustra los colores. Comprueba el carrusel real en el generador antes de exportar.</small></aside>
   </div>
  </template>
 </section>
</template>
<style scoped>
.visual-theme-manager{color:var(--text-primary,#fff);padding:20px;min-width:0}.visual-theme-manager header{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.visual-theme-manager h2{font-size:24px}.visual-theme-manager p,.visual-theme-manager small{color:var(--text-muted,#b8bfd5)}.theme-manager-layout{display:grid;grid-template-columns:200px minmax(0,1fr) minmax(220px,300px);gap:20px;margin-top:20px}.theme-manager-layout>*{min-width:0}.theme-manager-layout nav{display:flex;flex-direction:column;gap:8px}.visual-theme-manager button,.theme-file{border:1px solid var(--border,#ffffff33);background:var(--admin-surface,#171b31);color:inherit;padding:10px 12px;border-radius:10px;cursor:pointer;font:inherit;font-size:12px}.visual-theme-manager button:disabled{opacity:.5;cursor:not-allowed}.theme-manager-layout nav button{overflow-wrap:anywhere;text-align:left;display:grid;gap:6px}.theme-manager-layout nav .selected{border-color:#c084fc;background:#7024dc33}.theme-swatches{display:flex;gap:5px}.theme-swatches i{width:16px;height:16px;border-radius:50%;border:1px solid #ffffff44}.theme-draft>label{display:grid;gap:8px}.theme-draft textarea{width:100%;height:320px;resize:vertical;background:var(--admin-bg,#090c1b);color:inherit;border:1px solid var(--border,#ffffff33);border-radius:12px;padding:12px;font:12px/1.6 monospace;box-sizing:border-box}.theme-actions,.theme-integrations{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}.theme-integrations label{display:flex;align-items:center;gap:8px;font-size:13px}.theme-file input{display:none}.theme-error{color:#fda4af!important}.theme-draft details{margin-top:14px}.theme-draft summary{cursor:pointer;padding:10px}.theme-colors{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.theme-colors label{display:grid;gap:5px;font-size:11px}.theme-colors input{width:100%;min-width:0;background:var(--admin-bg,#090c1b);color:inherit;border:1px solid #ffffff33;padding:8px;border-radius:8px}@media(max-width:1200px){.theme-manager-layout{grid-template-columns:170px minmax(0,1fr)}.theme-manager-layout aside{grid-column:2}}@media(max-width:650px){.visual-theme-manager{padding:12px}.theme-manager-layout{grid-template-columns:minmax(0,1fr)}.theme-manager-layout nav{flex-direction:row;overflow-x:auto}.theme-manager-layout nav button{min-width:140px}.theme-manager-layout aside{grid-column:auto}.theme-colors{grid-template-columns:1fr}}
</style>
